import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {CortexEngine} from './engine.mjs';
import {ENVELOPE_DEFAULTS,audibleAttack,envelopeLevel,envelopeDuration} from './envelope.mjs';
const p=ENVELOPE_DEFAULTS,a=audibleAttack(p);assert.equal(envelopeLevel(0,p),0);assert.ok(Math.abs(envelopeLevel(a,p)-1)<1e-10);assert.ok(Math.abs(envelopeLevel(a+p.decay,p)-p.sustain)<1e-10);assert.equal(envelopeLevel(a+p.decay+.075,p),p.sustain);assert.ok(envelopeLevel(a+p.decay+.15+p.release/2,p)>0);assert.equal(envelopeLevel(envelopeDuration(p)+.001,p),0);
for(const params of[p,{attack:2,decay:4,sustain:1,release:5},{attack:.03,decay:.03,sustain:0,release:.03}])for(let t=0;t<12;t+=.001){const level=envelopeLevel(t,params);assert.ok(Number.isFinite(level)&&level>=0&&level<=1);}
const raw=await readFile(new URL('./assets/anatomy/brain-65536.xyz.f32',import.meta.url)),positions=new Float32Array(65536*3);for(let i=0;i<positions.length;i++)positions[i]=raw.readFloatLE(i*4);
const e=new CortexEngine(77);e.setGeometry(positions);e.set({coupling:0});const before=e.phase.slice(),nodeIndex=1024;e.excite(0,.65,'manual',0,nodeIndex);const event=e.drainEvents()[0];assert.equal(event.nodeIndex,nodeIndex);assert.deepEqual(event.seedPosition,Array.from(positions.subarray(nodeIndex*3,nodeIndex*3+3)));assert.equal(e.phase.reduce((n,v,i)=>n+(v!==before[i]),0),1);assert.ok(e.kickStrength.slice(1,4096).some(v=>v>0));
const phasesAtSeed=e.phase.slice();e.applyDueKicks(p.attack/2);const halfChanged=e.phase.reduce((n,v,i)=>n+(v!==before[i]),0);assert.ok(halfChanged>1&&halfChanged<4096);e.applyDueKicks(p.attack+1e-8);assert.equal(e.phase.reduce((n,v,i)=>n+(v!==before[i]),0),4096);for(let i=4096;i<65536;i++)assert.equal(e.phase[i],before[i]);assert.equal(e.pending.length,0);e.time=10;e.measure();assert.ok(e.activation.every(v=>v===0));
const slow=new CortexEngine(88);slow.setGeometry(positions);slow.set({attack:1.8,coupling:2.4});slow.excite(0,.65,'manual',0,nodeIndex);slow.drainEvents();slow.advanceEvents(1);assert.equal(slow.drainEvents().length,0);slow.advanceEvents(1.81);assert.equal(slow.drainEvents().length,2);slow.clearActivity();assert.ok(slow.kickStrength.every(v=>v===0));assert.equal(slow.pending.length,0);
console.log(JSON.stringify({ok:true,oneShotADSR:true,peakDecaySustainRelease:true,finiteSilentEnd:true,actualAnatomicalSeed:nodeIndex,immediatePhaseKicks:1,phaseKicksAtHalfAttack:halfChanged,phaseKicksAtFullAttack:4096,outsideRegionUnchanged:true,attackDelaysNextRegions:true,pauseCancelsPendingNodeArrivals:true},null,2));
